 @Override protected void onSaveInstanceState(Bundle b){b.putInt("tab",tab);b.putString("coin",coin);b.putString("period",period);b.putString("lesson",lessonId);b.putInt("stage",stage);super.onSaveInstanceState(b);}
 @Override protected void onNewIntent(Intent i){super.onNewIntent(i);setIntent(i);tab=i.getIntExtra("tab",tab);render();}
 @Override protected void onResume(){super.onResume();active=true;if(scene!=null)scene.resumeScene();main.removeCallbacks(tick);main.post(tick);requestSmoothDisplay();}
 @Override protected void onPause(){active=false;main.removeCallbacks(tick);if(scene!=null)scene.pauseScene();super.onPause();}
 @Override protected void onDestroy(){generation++;for(Future<?>f:pending)f.cancel(true);main.removeCallbacksAndMessages(null);super.onDestroy();}
 private void requestSmoothDisplay(){Display d=getWindowManager().getDefaultDisplay();Display.Mode current=d.getMode(),best=current;for(Display.Mode m:d.getSupportedModes())if(m.getPhysicalWidth()==current.getPhysicalWidth()&&m.getPhysicalHeight()==current.getPhysicalHeight()&&m.getRefreshRate()>best.getRefreshRate()&&m.getRefreshRate()<=144)best=m;WindowManager.LayoutParams p=getWindow().getAttributes();p.preferredDisplayModeId=best.getModeId();getWindow().setAttributes(p);}
 @Override public void onBackPressed(){goBack();}private void goBack(){if(!lessonId.isEmpty()){lessonId="";render();}else if(!reportId.isEmpty()){reportId="";render();}else if(tab!=0){tab=0;render();}else finish();}
 private <T>void task(Work<T>w,Done<T>d,Done<String>error){int g=generation;pending.removeIf(Future::isDone);Future<?>f=repo.io.submit(()->{try{T value=w.run();main.post(()->{if(g==generation&&!isDestroyed())d.accept(value);});}catch(Exception e){String msg=e.getMessage()==null?e.getClass().getSimpleName():e.getMessage();main.post(()->{if(g==generation&&!isDestroyed())error.accept(msg);});}});pending.add(f);}
 private void render(){generation++;refreshing=false;for(Future<?>f:pending)f.cancel(true);pending.clear();if(scene!=null){scene.pauseScene();scene=null;}body.removeAllViews();nav.removeAllViews();numbers.clear();periodViews.clear();String[]names={"行情","研报","课堂","资金","提醒"};for(int i=0;i<names.length;i++){final int t=i;weighted(nav,button(this,names[i],tab==i,()->{tab=t;lessonId="";reportId="";render();}));}scroll.scrollTo(0,0);
  switch(tab){case 0:market();break;case 1:if(reportId.isEmpty())reports();else reportDetail();break;case 2:if(lessonId.isEmpty())lessons();else lesson();break;case 3:flows();break;case 4:alerts();break;}
 }
