 private String label(String v){switch(v){case "1h":return"1 小时";case "4h":return"4 小时";case "8h":return"8 小时";case "12h":return"12 小时";case "1d":return"日线";case "1w":return"周线";case "daily":return"每日研究";case "weekly":return"每周研究";default:return v;}}
 private void link(LinearLayout c,String title,String url){if(url==null||!url.startsWith("https://"))return;c.addView(button(this,title+" ↗",false,()->{try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(ActivityNotFoundException e){Toast.makeText(this,"未安装浏览器",Toast.LENGTH_SHORT).show();}}));gap(c,8);}
 private String string(JSONObject j,String key){return j==null||j.isNull(key)?"":j.optString(key,"");}
