 private void intro(String a,String b,String c,boolean unused){intro(a,b,c);chips(body,new String[]{"BTC","ETH","SOL"},coin,v->{coin=v;multiAt=0;render();});LinearLayout q=panel(coin+" / USDT");quote=heading(this,"—",38);q.addView(quote);quoteMeta=text(this,"正在核对交易所时间与数据…",12,MUTED);q.addView(quoteMeta);gap(q,18);chips(q,Market.PERIODS,period,v->{period=v;render();});reading=text(this,"选中 K 线后，数值会出现在这里。",12,MUTED);reading.setTextIsSelectable(true);chart=new CandleChart(this,(bar,p)->reading.setText((bar.closed?"已闭合":"形成中 · 不用于确认")+"  "+time(bar.openAt)+"\nO "+n(bar.open)+"   H "+n(bar.high)+"   L "+n(bar.low)+"   C "+n(bar.close)+"\nVOL "+n(bar.volume)+" "+coin+"\nBB20  上 "+n(p.upper)+"  中 "+n(p.middle)+"  下 "+n(p.lower)+"\nMACD  DIF "+n(p.dif)+"  DEA "+n(p.dea)+"  柱 "+n(p.hist)+"\nRSI14  "+n(p.rsi)));
  q.addView(chart,new LinearLayout.LayoutParams(-1,dp(this,440)));LinearLayout controls=row(this);weighted(controls,button(this,"缩小",false,()->chart.zoom(1.3f)));weighted(controls,button(this,"放大",false,()->chart.zoom(.77f)));weighted(controls,button(this,"最新闭合",false,()->chart.latest()));q.addView(controls);Switch bands=new Switch(this);bands.setText("布林带 20 · 2");bands.setMinHeight(dp(this,48));bands.setChecked(true);bands.setOnCheckedChangeListener((v,on)->chart.bands(on));q.addView(bands);q.addView(reading);
  LinearLayout d=panel(label(period)+" · 收盘解读");interpretation=text(this,"等待确认数据…",15,INK);interpretation.setTextIsSelectable(true);d.addView(interpretation);gap(d,12);expand(d,"指标怎么读？","BB 使用 20 根收盘、总体标准差与 2 倍带宽。MACD 为 12/26/9，EMA 使用 SMA 种子，柱体 = DIF − DEA；某些平台显示 2 倍柱值。RSI14 使用 Wilder 平滑。\n\n数字默认取最近已闭合线，点击形成中的线会明确标识。价格指标同属一个证据家族，不能单独宣布牛熊转换。单根突破是候选；两根闭合保持同一箱体边界，也不代表已完成回踩。");d.addView(button(this,"重新获取",false,()->refreshMarket(true)));
  LinearLayout multi=panel("把不同周期放在一起");para(multi,"每个周期独立计算，日线与小时线可以出现分歧。");for(String p:Market.PERIODS){TextView t=button(this,label(p)+" · 等待更新",false,()->{period=p;render();});multi.addView(t);gap(multi,6);periodViews.put(p,t);}LinearLayout deriv=panel("杠杆温度");TextView out=text(this,"原生持仓量与资金费分开看；数据来自 Binance USDT 永续。",14,MUTED);deriv.addView(out);gap(deriv,12);deriv.addView(button(this,"读取 OI 与资金费",false,()->{out.setText("正在读取…");task(()->repo.derivatives(coin),j->{JSONObject oi=j.optJSONObject("oi"),f=j.optJSONObject("funding");out.setText("原生 OI  "+n(oi.optDouble("openInterest"))+" "+coin+"\n资金费  "+n(f.optDouble("lastFundingRate")*100)+"%\n下次结算  "+time(f.optLong("nextFundingTime"))+"\n来源时间  "+time(oi.optLong("time"))+"\n未做跨所汇总；美元 OI 不等同于原生 OI。");},e->out.setText("来源暂不可用："+e));}));refreshMarket(true);
 }
 private void refreshMarket(boolean force){if(refreshing||tab!=0)return;refreshing=true;String c=coin,p=period;task(()->repo.bars(c,p),b->{refreshing=false;Market.Bar last=b.bars.get(b.bars.size()-1);quote.setText(n(last.close));quoteMeta.setText((b.cached?"历史缓存":"Binance 现货快照")+" · "+time(b.asOf)+"\n前台约 15 秒更新 · 最新价可能来自形成中 K 线");chart.data(b.bars,b.points);interpretation.setText(explain(b.analysis));status.setText(b.cached?"缓存 · 暂停信号":"来源已响应");},e->{refreshing=false;quoteMeta.setText("暂未获得报价 · "+e);status.setText("等待来源");interpretation.setText("当前数据不可用，暂停判读。");});long now=System.currentTimeMillis();if(force||now-multiAt>60000){multiAt=now;for(String pp:Market.PERIODS){TextView v=periodViews.get(pp);task(()->repo.bars(c,pp),b->{if(v!=null)v.setText(label(pp)+"  ·  "+(b.analysis.valid()?b.analysis.trend+"\n"+b.analysis.structure:b.analysis.reason));},e->{if(v!=null)v.setText(label(pp)+" · 来源不可用");});}}}
 private String explain(Market.Analysis a){if(!a.valid())return a.reason+"\n缓存与未闭合数据不产生新信号。";return a.trend+"\n"+a.structure+"\n确认时间  "+time(a.closedAt)+"\n\n"+a.candle+"；相对前收盘 "+String.format(Locale.US,"%+.2f%%",a.change)+"\n相对前 20 根成交量："+n(a.volumeRatio)+" 倍\n\nMACD · "+a.macdText+"\n\nRSI · "+a.rsiText+(a.box==null?"":"\n\n固定箱体 "+n(a.box.low)+" — "+n(a.box.high))+"\n\n价格形态不代表机制健康或个人买卖许可。";}

 private LinearLayout reportList;private void reports(){intro("RESEARCH JOURNAL","把信息，连成理解。","读最新一期，也保留当时的证据和反证。");chips(body,new String[]{"daily","weekly"},reportPeriod,v->{reportPeriod=v;render();});LinearLayout c=panel("从这段对话到手机");para(c,"在维护观潮的这个项目里分析 BTC，再加一句“更新”。助手核验并发布新一期后，这里自动读取，不用复制或导入。未发布前，不会凭空生成一份日报。");c.addView(button(this,"检查云端新一期",false,()->loadReports()));reportList=column(this);body.addView(reportList);loadReports();}
 private void loadReports(){reportAt=System.currentTimeMillis();task(()->repo.document("reports"),p->{reports=p.data;if(reportList==null)return;reportList.removeAllViews();TextView state=text(this,p.state+" · revision "+reports.optString("revision")+(p.issue.isEmpty()?"":"\n云端请求失败："+p.issue),11,MUTED);reportList.addView(state);gap(reportList,12);JSONArray a=reports.optJSONArray("reports");if(a!=null)for(int i=a.length()-1;i>=0;i--){JSONObject r=a.optJSONObject(i);if(r==null||!r.optString("period").equals(reportPeriod))continue;LinearLayout c=card(this);c.addView(text(this,r.optString("date")+" · "+(r.optString("kind").equals("market")?"市场研究":"方法 / 使用指南"),11,MUTED));gap(c,10);c.addView(heading(this,r.optString("title"),23));gap(c,10);para(c,r.optString("summary"));String id=r.optString("id");c.addView(button(this,"打开这一期  →",false,()->{reportId=id;render();}));reportList.addView(c);}},e->{if(reportList!=null){reportList.removeAllViews();reportList.addView(text(this,"报告读取失败："+e,14,RED));}});}
 private JSONObject find(JSONArray a,String id){if(a!=null)for(int i=0;i<a.length();i++){JSONObject j=a.optJSONObject(i);if(j!=null&&j.optString("id").equals(id))return j;}return null;}
 private boolean has(JSONArray a,String id){if(a!=null)for(int i=0;i<a.length();i++)if(a.optString(i).equals(id))return true;return false;}
 private void reportDetail(){JSONObject r=reports==null?null:find(reports.optJSONArray("reports"),reportId);if(r==null){reportId="";reports();return;}body.addView(button(this,"← 所有研究",false,()->{reportId="";render();}));gap(body,14);intro(r.optString("edition"),r.optString("title"),r.optString("summary"));LinearLayout meta=panel("这期的适用范围");para(meta,string(r,"notice"));String until=string(r,"validUntil");if(!until.isEmpty())try{para(meta,(Instant.parse(until).toEpochMilli()<System.currentTimeMillis()?"已到复核期限 · ":"复核期限 · ")+until);}catch(Exception e){para(meta,"复核时间格式异常，暂不作为当前判断。");}para(meta,"发布时间："+(string(r,"publishedAt").isEmpty()?"方法资料，无行情发布时间":r.optString("publishedAt")));
  JSONArray take=r.optJSONArray("takeaways");if(take!=null)for(int i=0;i<take.length();i++){JSONObject t=take.optJSONObject(i);if(t!=null){LinearLayout c=panel(t.optString("title"));para(c,t.optString("text"));}}
  JSONArray sections=r.optJSONArray("sections");if(sections!=null)for(int i=0;i<sections.length();i++){JSONObject t=sections.optJSONObject(i);if(t!=null){LinearLayout c=panel(t.optString("title"));para(c,t.optString("body"));para(c,"来源 · "+t.optString("source"));}}
  JSONArray assets=r.optJSONArray("assets");if(assets!=null)for(int i=0;i<assets.length();i++){JSONObject a=assets.optJSONObject(i);if(a==null)continue;LinearLayout c=panel(a.optString("symbol"));para(c,"趋势 · "+a.optString("trend")+"\n健康 · "+a.optString("health")+"\n风险 · "+a.optString("risk"));para(c,a.optString("action"));expand(c,"证据与缺口",join(a.optJSONArray("evidence"))+"\n\n缺失\n"+join(a.optJSONArray("missing")));para(c,"失效 / 复核 · "+a.optString("invalidation")+"\n"+a.optString("nextReview"));}
  JSONArray events=reports.optJSONArray("events");if(events!=null)for(int i=0;i<events.length();i++){JSONObject e=events.optJSONObject(i);if(e==null||!has(r.optJSONArray("events"),e.optString("id")))continue;LinearLayout c=panel(e.optString("title"));para(c,e.optString("status"));para(c,e.optString("why"));expand(c,"拆开检查",join(e.optJSONArray("checklist")));JSONArray scenarios=e.optJSONArray("scenarios");if(scenarios!=null)for(int k=0;k<scenarios.length();k++){JSONObject s=scenarios.optJSONObject(k);if(s!=null)expand(c,s.optString("label")+" · "+s.optString("title"),s.optString("body")+"\n"+s.optString("watch"));}}
  LinearLayout qa=panel("就这份报告，继续理解");para(qa,"检索本期引用的解释卡。这里没有连接实时 AI，也不会编造当前市场数据。");EditText input=new EditText(this);input.setHint("例如：RSI、健康度、持仓量");input.setSingleLine(true);qa.addView(input);LinearLayout answers=column(this);JSONArray knowledge=reports.optJSONArray("knowledge");Runnable search=()->{answers.removeAllViews();String query=input.getText().toString().trim().toLowerCase(Locale.ROOT);int hits=0;if(knowledge!=null)for(int i=0;i<knowledge.length();i++){JSONObject k=knowledge.optJSONObject(i);if(k==null||!has(r.optJSONArray("qa"),k.optString("id")))continue;String searchable=k.toString().toLowerCase(Locale.ROOT);if(!query.isEmpty()&&!searchable.contains(query))continue;expand(answers,k.optString("question",k.optString("title")),k.optString("answer",k.optString("body")));hits++;}if(hits==0)para(answers,"本期没有匹配的解释。可以回到对话继续问，并要求更新。");};qa.addView(button(this,"查找解释",false,search));qa.addView(answers);search.run();LinearLayout end=panel("反证与下一步");para(end,r.optString("counterEvidence"));para(end,r.optString("nextReview"));JSONArray src=r.optJSONArray("sources");if(src!=null)for(int i=0;i<src.length();i++){JSONObject s=src.optJSONObject(i);if(s==null)continue;para(end,s.optString("title")+"\n"+s.optString("status")+"\n"+string(s,"observedAt"));link(end,"查看来源",string(s,"url"));}
 }

 private void lessons(){intro("SPATIAL CLASSROOM","让抽象，变得可触碰。","拖动参数、拆开模型，亲手看看一件事怎样发生。");LinearLayout h=panel("一个数字，会怎样传导？");para(h,"9 个小实验 · 每次约 2 分钟\n所有参数都是明确的教学假设，数值可以展开核算。");for(int i=0;i<catalog.length();i++){JSONObject l=catalog.optJSONObject(i);if(l==null)continue;LinearLayout c=panel(String.format(Locale.US,"%02d  /  ",i+1)+l.optString("title"));para(c,l.optString("subtitle"));c.addView(button(this,"进入实验  →",false,()->{lessonId=l.optString("id");stage=0;expanded=false;render();}));}}
 private void lesson(){lesson=find(catalog,lessonId);if(lesson==null){lessonId="";lessons();return;}body.addView(button(this,"← 全部课堂",false,()->{lessonId="";render();}));gap(body,12);intro("A SMALL EXPERIMENT",lesson.optString("title"),lesson.optString("subtitle"));LinearLayout c=panel("用手改变一个条件");para(c,lesson.optString("setup"));ActivityManager am=(ActivityManager)getSystemService(ACTIVITY_SERVICE);if(am.getDeviceConfigurationInfo().reqGlEsVersion>=0x20000){scene=new SpatialLesson(this,i->modelDetail(i));scene.reduce(prefs.getBoolean("reduce",false));c.addView(scene,new LinearLayout.LayoutParams(-1,dp(this,310)));if(active)scene.resumeScene();}else para(c,"此设备不支持三维渲染，下面仍可完整操作与核算。");control=text(this,"",14,INK);gap(c,12);c.addView(control);double min=lesson.optDouble("min"),max=lesson.optDouble("max"),step=lesson.optDouble("step",1);SeekBar slider=new SeekBar(this);slider.setMax((int)Math.round((max-min)/step));slider.setMinHeight(dp(this,48));slider.setContentDescription(lesson.optString("control"));double value=prefs.getFloat("lesson_"+lessonId,(float)lesson.optDouble("value"));value=Math.max(min,Math.min(max,value));slider.setProgress((int)Math.round((value-min)/step));c.addView(slider);slider.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}public void onProgressChanged(SeekBar s,int p,boolean user){double value=min+p*step;updateLesson(value);if(user)prefs.edit().putFloat("lesson_"+lessonId,(float)value).apply();}});
  LinearLayout values=column(this);for(int i=0;i<3;i++){final int index=i;TextView t=button(this,"",false,()->modelDetail(index));numbers.add(t);values.addView(t);gap(values,6);}c.addView(values);c.addView(button(this,"展开 / 合拢模型",false,()->{expanded=!expanded;if(scene!=null)scene.expanded(expanded);}));gap(c,8);para(c,"可左右旋转、点选模型。三种颜色与下面三项数值一一对应，零值位于网格，负值在网格下方。");updateLesson(value);
  LinearLayout steps=panel("把过程拆成四步");lessonStep=text(this,"",16,INK);steps.addView(lessonStep);gap(steps,14);LinearLayout controls=row(this);weighted(controls,button(this,"上一步",false,()->{stage=Math.max(0,stage-1);updateStage();}));weighted(controls,button(this,"下一步",false,()->{stage=Math.min(3,stage+1);updateStage();}));steps.addView(controls);updateStage();link(steps,"延伸阅读",lesson.optString("source"));
 }
 private void updateLesson(double value){result=Lessons.calculate(lessonId,value);control.setText(lesson.optString("control")+"  "+n(value)+lesson.optString("unit"));for(int i=0;i<numbers.size();i++)numbers.get(i).setText(result.labels[i]+"     "+n(result.values[i])+" "+result.unit);if(scene!=null)scene.values(result);}
 private void updateStage(){JSONArray steps=lesson.optJSONArray("stages");if(steps==null||steps.length()==0)return;stage=Math.max(0,Math.min(stage,steps.length()-1));JSONObject s=steps.optJSONObject(stage);lessonStep.setText((stage+1)+" / "+steps.length()+"\n\n"+s.optString("title")+"\n\n"+s.optString("body")+"\n\n"+s.optString("caveat"));}
